  "inlineSchema": "datasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// User role definition\nenum Role {\n  ADMIN\n  FLEET_MANAGER\n  DISPATCHER\n  SAFETY_OFFICER\n  FINANCIAL_ANALYST\n}\n\n// Vehicle operating status\nenum VehicleStatus {\n  AVAILABLE\n  ON_TRIP\n  IN_SHOP\n  RETIRED\n}\n\n// Driver status\nenum DriverStatus {\n  AVAILABLE\n  ON_TRIP\n  OFF_DUTY\n  SUSPENDED\n}\n\n// Trip progress status\nenum TripStatus {\n  DRAFT\n  DISPATCHED\n  COMPLETED\n  CANCELLED\n}\n\n// Maintenance status logs\nenum MaintenanceStatus {\n  SCHEDULED\n  IN_PROGRESS\n  COMPLETED\n}\n\n// Allowed expense categories\nenum ExpenseCategory {\n  TOLL\n  PARKING\n  DRIVER_ALLOWANCE\n  REPAIR\n  MAINTENANCE\n  INSURANCE\n  PERMIT\n  FINE\n  MISCELLANEOUS\n}\n\n// User model for platform access\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  role      Role\n  name      String\n  phone     String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  tripsDispatched Trip[]\n  auditLogs       AuditLog[]\n  driverProfile   Driver?\n\n  @@index([email])\n}\n\n// Vehicle assets\nmodel Vehicle {\n  id                 String        @id @default(uuid())\n  registrationNumber String        @unique\n  make               String\n  model              String\n  year               Int\n  capacity           Float // Cargo payload weight capacity\n  odometer           Float // Odometer reading in KM/Miles\n  status             VehicleStatus @default(AVAILABLE)\n  createdAt          DateTime      @default(now())\n  updatedAt          DateTime      @updatedAt\n\n  // Relations\n  trips           Trip[]\n  maintenanceLogs MaintenanceLog[]\n  fuelLogs        FuelLog[]\n  expenses        Expense[]\n\n  @@index([registrationNumber])\n  @@index([status])\n}\n\n// Drivers profile\nmodel Driver {\n  id            String       @id @default(uuid())\n  name          String\n  email         String       @unique\n  phone         String\n  licenseNumber String       @unique\n  licenseExpiry DateTime\n  safetyScore   Float        @default(100.0) // Metric 0 - 100\n  status        DriverStatus @default(AVAILABLE)\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n\n  // Link user profile if driver can access portal\n  userId String? @unique\n  user   User?   @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  // Relations\n  trips    Trip[]\n  fuelLogs FuelLog[]\n  expenses Expense[]\n\n  @@index([email])\n  @@index([licenseNumber])\n  @@index([status])\n}\n\n// Core Operations - Trips\nmodel Trip {\n  id            String     @id @default(uuid())\n  tripNumber    String     @unique\n  vehicleId     String\n  vehicle       Vehicle    @relation(fields: [vehicleId], references: [id], onDelete: Restrict)\n  driverId      String\n  driver        Driver     @relation(fields: [driverId], references: [id], onDelete: Restrict)\n  dispatcherId  String\n  dispatcher    User       @relation(fields: [dispatcherId], references: [id], onDelete: Restrict)\n  status        TripStatus @default(DRAFT)\n  cargoWeight   Float\n  startOdometer Float\n  endOdometer   Float?\n  startTime     DateTime?\n  endTime       DateTime?\n  routeDetails  String?\n  revenue       Float?\n  fuelUsed      Float?\n  cancelReason  String?\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n\n  // Relations\n  expenses Expense[]\n\n  @@index([tripNumber])\n  @@index([status])\n  @@index([vehicleId])\n  @@index([driverId])\n}\n\n// Maintenance operations logs\nmodel MaintenanceLog {\n  id          String            @id @default(uuid())\n  vehicleId   String\n  vehicle     Vehicle           @relation(fields: [vehicleId], references: [id], onDelete: Cascade)\n  description String\n  cost        Float\n  status      MaintenanceStatus @default(SCHEDULED)\n  startDate   DateTime\n  endDate     DateTime?\n  createdAt   DateTime          @default(now())\n  updatedAt   DateTime          @updatedAt\n\n  @@index([vehicleId])\n  @@index([status])\n}\n\n// Refuel Logs\nmodel FuelLog {\n  id           String   @id @default(uuid())\n  vehicleId    String\n  vehicle      Vehicle  @relation(fields: [vehicleId], references: [id], onDelete: Cascade)\n  driverId     String\n  driver       Driver   @relation(fields: [driverId], references: [id], onDelete: Restrict)\n  liters       Float\n  costPerLiter Float\n  totalCost    Float // Computed as liters * costPerLiter\n  odometer     Float // Current odometer during refuel\n  refuelDate   DateTime\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([vehicleId])\n  @@index([driverId])\n}\n\n// Expense Ledger\nmodel Expense {\n  id          String          @id @default(uuid())\n  vehicleId   String?\n  vehicle     Vehicle?        @relation(fields: [vehicleId], references: [id], onDelete: Cascade)\n  tripId      String?\n  trip        Trip?           @relation(fields: [tripId], references: [id], onDelete: Cascade)\n  driverId    String?\n  driver      Driver?         @relation(fields: [driverId], references: [id], onDelete: SetNull)\n  amount      Float\n  category    ExpenseCategory\n  date        DateTime\n  description String\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  @@index([vehicleId])\n  @@index([tripId])\n  @@index([category])\n}\n\n// Security & Audit Compliance Logs\nmodel AuditLog {\n  id         String   @id @default(uuid())\n  userId     String?\n  user       User?    @relation(fields: [userId], references: [id], onDelete: SetNull)\n  action     String // E.g., \"USER_LOGIN\", \"TRIP_DISPATCH\"\n  entityName String? // E.g., \"Vehicle\", \"Trip\"\n  entityId   String?\n  details    String? // JSON string containing payload summary\n  ipAddress  String?\n  userAgent  String?\n  timestamp  DateTime @default(now())\n\n  @@index([userId])\n  @@index([action])\n  @@index([timestamp])\n}\n",
